def login(password, school_id, carrier) -> requests.Response:
    ip = list(filter(lambda x: x[4][0].startswith('10'),
                     socket.getaddrinfo(socket.gethostname(), None)))[0][4][0]
    return requests.get(
        f'http://10.10.90.2:801/eportal/portal/login?'
        f'user_account=%2C0%2C{school_id}%40{carrier}&'
        f'user_password={password}&'
        f'wlan_user_ip={ip}&'
    )


def check_network_connection():
    try:
        return requests.get('https://www.baidu.com', timeout=1).status_code == 200
    except:
        return False


def run(password, school_id, carrier):
    while True:
        name = pywifi.PyWiFi().interfaces()[0].scan_results()[0].ssid
        if name.startswith('CMCC-GNNUN'):
            response = login(password, school_id, carrier)
            if response.text != 'jsonpReturn({"result":1,"msg":"Portal协议认证成功！"});':
                print(response.text)
                time.sleep(30)
                continue
            else:
                while check_network_connection():
                    sleep(10)
        else:
            time.sleep(10)


def main(config):
    password = urllib.parse.quote(config["password"])
    school_id = urllib.parse.quote(config["school_id"])
    carrier = urllib.parse.quote(carrier_id[config["carrier"]])
    run(password, school_id, carrier)


def gui():
    win = tkinter.Tk()
    win.title("校园网自动登录-设置")
    win.iconbitmap(icon_file)
    win.geometry("400x200")
    win.resizable(False, False)

    font1 = ("微软雅黑", 24)
    font2 = ("微软雅黑", 20)

    # 运营商
    carrier_label = tkinter.Label(win, text="运营商：", font=font1)
    carrier_label.grid(row=0, column=0)
    carrier_var = tkinter.StringVar()
    carrier_var.set("移动")
    carrier_menu = tkinter.OptionMenu(win, carrier_var, "移动", "电信", "联通")
    carrier_menu.config(font=font2)
    carrier_menu.grid(row=0, column=1)

    # 学号
    school_id_label = tkinter.Label(win, text="学号：", font=font1)
    school_id_label.grid(row=1, column=0)
    school_id_var = tkinter.StringVar()
    school_id_var.set("")
    school_id_entry = tkinter.Entry(win, textvariable=school_id_var, font=font2)
    school_id_entry.grid(row=1, column=1)

    # 密码
    password_label = tkinter.Label(win, text="密码：", font=font1)
    password_label.grid(row=2, column=0)
    password_var = tkinter.StringVar()
    password_var.set("")
    password_entry = tkinter.Entry(win, textvariable=password_var, font=font2)
    password_entry.grid(row=2, column=1)

    # 确认按钮
    def confirm():
        config = {
            "carrier": carrier_var.get(),
            "school_id": school_id_var.get(),
            "password": password_var.get(),
        }
        with open(config_file, "w") as f:
            f.write(json.dumps(config))
        create_shortcut(__file__, shortcut_file)
        win.destroy()
        main(config)

    confirm_button = tkinter.Button(win, text="确认", font=font2, command=confirm)
    confirm_button.grid(row=3, column=0, columnspan=2)

    win.mainloop()


def create_shortcut(path, from_path):
    winshell.CreateShortcut(
        Path=from_path,
        Target=path,
        Icon=(path, 0),
        Description="校园网自动登录"
    )


if __name__ == '__main__':
    init()
